    (297, 'Challenger Model', 'Total Verizon - Below the line (BTL)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Total Verizon - Total Interest Expense] + [Total Verizon - Equity (Income) Loss from Unconsolidated Business] + [Total Verizon - Other Income and Expense] + [Total Verizon - Noncontrolling Interest]', TRUE, NULL)
  ])
)
SELECT dim, value, COUNT(DISTINCT deeper_node) AS deeper_nodes FROM (
SELECT 'Profit_Center' AS dim, TRIM(c.ProfitCentre) AS value, h2.node AS deeper_node FROM config_csv c JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h1 ON h1.dimension_name = 'Profit_Center' AND h1.parent = TRIM(c.ProfitCentre) AND (CASE WHEN NULLIF(TRIM(c.ProfitCentreHierarchyName), '') IS NULL THEN h1.is_primary = TRUE ELSE h1.hierarchy_name = NULLIF(TRIM(c.ProfitCentreHierarchyName), '') END) JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h2 ON h2.dimension_name = 'Profit_Center' AND h2.parent = h1.node AND (CASE WHEN NULLIF(TRIM(c.ProfitCentreHierarchyName), '') IS NULL THEN h2.is_primary = TRUE ELSE h2.hierarchy_name = NULLIF(TRIM(c.ProfitCentreHierarchyName), '') END) LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` h3 ON h3.dimension_name = 'Profit_Center' AND h3.parent = TRIM(c.ProfitCentre) AND h3.node = h2.node AND (CASE WHEN NULLIF(TRIM(c.ProfitCentreHierarchyName), '') IS NULL THEN h3.is_primary = TRUE ELSE h3.hierarchy_name = NULLIF(TRIM(c.ProfitCentreHierarchyName), '') END) WHERE (c.Formula IS NULL OR TRIM(c.Formula) = '') AND NOT (c.ProfitCentre IS NULL OR TRIM(c.ProfitCentre) = '' OR UPPER(TRIM(c.ProfitCentre)) IN ('ALL', 'NA')) AND h3.node IS NULL
UNION ALL
